def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/environment/input/water-body-testing-2013.csv'
    return pd.read_csv(path)

def process(water2012, water2013) -> pd.DataFrame:
    import pandas as pd

    def standardize(df: pd.DataFrame) -> pd.DataFrame:
        out = df.copy()
        out.columns = [c.strip() for c in out.columns]
        # Find beach/site column
        beach_candidates = [
            'Beach', 'BEACH', 'Beach Name', 'BEACH_NAME', 'Location', 'LOCATION',
            'Site', 'SITE', 'Sampling Location', 'SAMPLING_LOCATION', 'Water Body', 'WATER_BODY'
        ]
        beach_col = next((c for c in out.columns if c in beach_candidates), None)
        if beach_col is None:
            # fallback: first column containing 'beach' or 'site'
            for c in out.columns:
                cl = c.lower()
                if 'beach' in cl or 'site' in cl or 'location' in cl:
                    beach_col = c
                    break
        if beach_col is None:
            raise ValueError(f"Cannot identify beach/site column from: {list(out.columns)}")

        # Find exceedance / result indicator column
        exceed_candidates = [
            'Exceedance', 'EXCEEDANCE', 'Bacterial Exceedance', 'BACTERIAL_EXCEEDANCE',
            'Exceeded', 'EXCEEDED', 'Exceeds Standard', 'EXCEEDS_STANDARD',
            'Standard Exceeded', 'STANDARD_EXCEEDED', 'Over Standard', 'OVER_STANDARD'
        ]
        exc_col = next((c for c in out.columns if c in exceed_candidates), None)
        if exc_col is None:
            for c in out.columns:
                cl = c.lower()
                if 'exceed' in cl:
                    exc_col = c
                    break
        if exc_col is None:
            raise ValueError(f"Cannot identify exceedance column from: {list(out.columns)}")

        s = out[exc_col]
        # map to boolean: True for exceedance
        if pd.api.types.is_bool_dtype(s):
            exc = s
        else:
            # attempt numeric
            sn = pd.to_numeric(s, errors='coerce')
            if sn.notna().any():
                exc = sn.astype('float') > 0
            else:
                st = s.astype(str).str.strip().str.lower()
                true_vals = {'yes','y','true','t','1','exceed','exceeded','exceeds','above','over'}
                false_vals = {'no','n','false','f','0','not exceed','not exceeded','below','under'}
                exc = st.map(lambda v: True if v in true_vals else (False if v in false_vals else pd.NA))
        out2 = pd.DataFrame({
            'beach': out[beach_col].astype(str).str.strip(),
            'exceed': exc
        })
        out2 = out2[out2['beach'].ne('')]
        out2 = out2[out2['exceed'].notna()]
        out2['exceed'] = out2['exceed'].astype(bool)
        return out2

    d12 = standardize(water2012)
    d13 = standardize(water2013)

    rate12 = d12.groupby('beach').agg(samples12=('exceed','size'), exceed12=('exceed','sum')).reset_index()
    rate12['rate12'] = rate12['exceed12'] / rate12['samples12']

    rate13 = d13.groupby('beach').agg(samples13=('exceed','size'), exceed13=('exceed','sum')).reset_index()
    rate13['rate13'] = rate13['exceed13'] / rate13['samples13']

    # Exclude beaches with no samples in 2012 -> inner join
    merged = rate12.merge(rate13, on='beach', how='inner')
    countHigher = (merged['rate13'] > merged['rate12']).sum()
    return pd.DataFrame([{'countHigher2013vs2012': int(countHigher)}])
